%[text] 发现2:Transfer 过程是layer 2为模版的，L2编码了早期的记忆，晚期的动作目的，并在迁移过程中共用了L2，而L5参与了行为
%[text:tableOfContents]{"heading":"目录"}
%[text] # 学习早期
%[text] 2层功能：记录刺激
%[text] 1. 时间提前
%[text] 2. 活动低
%[text] 3. 对cue不响应 \
%[text] L5无时间提前
%[text] L2早于L5
%[text] ## A
%[text] 群体活动总览：1s内达到基线3倍标准差的所有细胞
ALB=TransferLearning.AudioLightBaseline; %[output:0290c75c] %[output:5dd1d0d7] %[output:164258c3] %[output:3f1c0f3e] %[output:69487fdf] %[output:13838bf5] %[output:5b0f1eb6] %[output:940a3b48] %[output:7cc97128] %[output:263f4b5d] %[output:86efb16a] %[output:65e8ad70] %[output:2f93f5c5] %[output:03f6e84a] %[output:8dfc1587] %[output:1f9c99b4] %[output:2abe3ff1] %[output:2a8afa47] %[output:739c7eba] %[output:13a26951] %[output:7a282943] %[output:98bf4755] %[output:03ab4e39] %[output:44d89ccc] %[output:0bc891d8] %[output:11a365e3] %[output:9e31256c] %[output:317e34c4] %[output:6c7382ea] %[output:99b9b323] %[output:8bffe50d] %[output:18d2ee80] %[output:77a84cf1]
QueryTablePath=TransferLearning.ProjectPath('查询表.xlsx');
%%
EnsembleA=UniExp.NtatsCellStrip(ALB.QueryNTATS(UniExp.ReadQueryTable(QueryTablePath,'Fig2A'),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median)); %[output:7fb1b0a6]
[~,Index]=ismember(EnsembleA.CellUID,ALB.Cells.CellUID);
ZLayer=ALB.Cells.ZLayer(Index);
%%
EnsembleLogical=max(EnsembleA.NTATS.AudioWater(:,25:32),[],2)>std(EnsembleA.NTATS.AudioWater(:,1:24),[],2)*3;
Layer2Logical=ZLayer=="MOp2/3";
Layer5Logical=ZLayer=="MOp5";
Ensemble2=Layer2Logical&EnsembleLogical;
Ensemble5=Layer5Logical&EnsembleLogical;
%%
LayerTitles=["Layer2 "+MATLAB.SignificantFixedpoint(sum(Ensemble2)/sum(Layer2Logical)*100,2)+"%","Layer5 "+MATLAB.SignificantFixedpoint(sum(Ensemble5)/sum(Layer5Logical)*100,2)+"%"];
Phases=["AudioOnly","WaterOnly","AudioWater"];
HLData=table;
HLData.(LayerTitles(1))=permute(EnsembleA.NTATS{Ensemble2,:,Phases},[3,1,2]);
HLData.(LayerTitles(2))=permute(EnsembleA.NTATS{Ensemble5,:,Phases},[3,1,2]);
HLData.Properties.RowNames=Phases';
%%
XLine=timetable;
%timetable的局限性，必须先制定列后指定时间
XLine.LineStyle=":k";
XLine.Time=seconds(0);
Fig=figure; %[output:3395302a]
[Layout,Axes,Lines,ColorBar]=UniExp.HeatmapLine(HLData(:,LayerTitles),seconds([-3,3]),XLine=XLine); %[output:3395302a]
legend(Lines(:,1),["Layer 2","Layer 5"],Location=MATLAB.Graphics.OptimizedLegendLocation(Lines(:,1))); %[output:3395302a]
ylabel(Axes(3,1),'z-score ± SEM'); %[output:3395302a]
ColorBar.Label.String='z-score'; %[output:3395302a]
MATLAB.Graphics.FigureAspectRatio(8,5,MATLAB.Flags.Narrow); %[output:3395302a]
title(Layout,'Ensemble Naive'); %[output:3395302a]
print(Fig,TransferLearning.ProjectPath('Fig2A.svg'),'-dsvg'); %[output:3395302a]
%%
%[text] ## B
Fig=figure; %[output:9b9b8d4c]
Layout=tiledlayout(2,2,TileSpacing='tight',Padding='compact');%Padding如果用tight，右边坐标轴会出界 %[output:9b9b8d4c]
%[text] 2层时间提前：AudioWater相比于AudioOnly
GroupNtats=UniExp.NtatsCellStrip(ALB.QueryNTATS(UniExp.ReadQueryTable(QueryTablePath,'Fig2B12'),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median)); %[output:783df95b]
EnsembleB12=GroupNtats(max(GroupNtats.NTATS.AudioWater(:,25:32),[],2)>std(GroupNtats.NTATS.AudioWater(:,1:24),[],2)*3,:);
[~,RisingTime]=max(diff(EnsembleB12.NTATS{:,25:end,["AudioOnly","AudioWater"]},1,2),[],2);
RisingTime=array2table(permute(RisingTime*milliseconds(125),[1,3,2]),'VariableNames',["🔊","🔊💧"]);
nexttile; %[output:9b9b8d4c]
UniExp.BarScatterCompare(RisingTime,false,table(["🔊","🔊💧"],'VariableNames',"GroupPair")); %[output:9b9b8d4c]
ylabel('Rising time (s)'); %[output:9b9b8d4c]
title('Layer 2'); %[output:9b9b8d4c]
YLim=ylim;
ylim([0,YLim(2)]); %[output:9b9b8d4c]
%[text] 2层活动强度：AudioWater比AudioOnly强
Response=max(EnsembleB12.NTATS(:,25:32,:),[],2);
nexttile; %[output:9b9b8d4c]
UniExp.BarScatterCompare(table(Response.AudioOnly,Response.AudioWater,'VariableNames',["🔊","🔊💧"]),false,table(["🔊","🔊💧"],'VariableNames',"GroupPair")); %[output:9b9b8d4c]
ylabel('Max z-score in 1s'); %[output:9b9b8d4c]
title('Layer 2'); %[output:9b9b8d4c]
YLim=ylim;
ylim([0,YLim(2)]); %[output:9b9b8d4c]
%[text] 5层：AudioWater与WaterOnly时间比较
GroupNtats=UniExp.NtatsCellStrip(ALB.QueryNTATS(UniExp.ReadQueryTable(QueryTablePath,'Fig2B3'),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median)); %[output:4033d556]
EnsembleB3=GroupNtats(max(GroupNtats.NTATS.AudioWater(:,25:32),[],2)>std(GroupNtats.NTATS.AudioWater(:,1:24),[],2)*3,:);
[~,RisingTime]=max(diff(EnsembleB3.NTATS{:,25:end,["WaterOnly","AudioWater"]},1,2),[],2);
nexttile; %[output:9b9b8d4c]
UniExp.BarScatterCompare(array2table(permute(RisingTime*milliseconds(125),[1,3,2]),'VariableNames',["💧","🔊💧"]),false,table(["💧","🔊💧"],'VariableNames',"GroupPair")); %[output:9b9b8d4c]
ylabel('Rising time (s)'); %[output:9b9b8d4c]
title('Layer 5'); %[output:9b9b8d4c]
YLim=ylim;
ylim([0,YLim(2)]); %[output:9b9b8d4c]
%[text] L2早于L5
EnsembleB4=ALB.QueryNTATS(UniExp.ReadQueryTable(QueryTablePath,'Fig2B4'),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median); %[output:5a9363dc]
RisingTime=struct;
for L=["Layer2","Layer5"]
	NTATS=EnsembleB4.(L).NTATS;
	NTATS=NTATS(max(NTATS(:,25:32),[],2)>std(NTATS(:,1:24),[],2)*3,:);
	[~,RT]=max(diff(NTATS(:,25:end),1,2),[],2);
	RisingTime.(L)=RT*milliseconds(125);
end
nexttile; %[output:9b9b8d4c]
UniExp.BarScatterCompare(RisingTime,false,table(["Layer2","Layer5"],'VariableNames',"GroupPair")); %[output:9b9b8d4c]
ylabel('Rising time (s)'); %[output:9b9b8d4c]
YLim=ylim;
ylim([0,YLim(2)]); %[output:9b9b8d4c]
MATLAB.Graphics.FigureAspectRatio(8,5,MATLAB.Flags.Narrow); %[output:9b9b8d4c]
Layout.Padding="compact";
print(Fig,TransferLearning.ProjectPath('Fig2B.svg'),'-dsvg'); %[output:9b9b8d4c]
%%
%[text] # 学习后
%[text] L2功能：指导L5行动
%[text] 1. 时间提前
%[text] 2. 活动高
%[text] 3. 形成correlation ensemble？ \
%[text] L5
%[text] 1. 时间提前
%[text] 2. 响应增强 \
%[text] L2与L5 同时
%[text] ## C
EnsembleCDE=ALB.QueryNTATS(UniExp.ReadQueryTable(QueryTablePath,'Fig2CD'),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median); %[output:7583b186]
%%
EnsembleC=UniExp.NtatsCellStrip(EnsembleCDE);
%%
[~,Index]=ismember(EnsembleC.CellUID,ALB.Cells.CellUID);
ZLayer=ALB.Cells.ZLayer(Index);
Layer5Logical=ZLayer=="MOp5";
Layer2Logical=~Layer5Logical;
%%
EnsembleLogical=max(EnsembleC.NTATS.Learned(:,25:32),[],2)>std(EnsembleC.NTATS.Learned(:,1:24),[],2)*3;
Ensemble2=Layer2Logical&EnsembleLogical;
Ensemble5=Layer5Logical&EnsembleLogical;
LayerTitles=["Layer2 "+MATLAB.SignificantFixedpoint(sum(Ensemble2)/sum(Layer2Logical)*100,2)+"%","Layer5 "+MATLAB.SignificantFixedpoint(sum(Ensemble5)/sum(Layer5Logical)*100,2)+"%"];
Phases=["Naive","Learned"];
%%
XLine=timetable;
%timetable的局限性，必须先制定列后指定时间
XLine.LineStyle=[":k";"-k"];
XLine.Time=seconds([0;1]);
%%
Fig=figure; %[output:9305bb70]
[Layout,Axes,Lines,ColorBar]=UniExp.HeatmapLine(table(permute(EnsembleC.NTATS{Ensemble2,:,Phases},[3,1,2]),permute(EnsembleC.NTATS{Ensemble5,:,Phases},[3,1,2]),'VariableNames',LayerTitles,'RowNames',Phases),seconds([-3,3]),XLine=XLine); %[output:9305bb70]
legend(Lines(:,1),["Layer 2","Layer 5"],Location=MATLAB.Graphics.OptimizedLegendLocation(Lines(:,1))); %[output:9305bb70]
ylabel(Axes(3,1),'z-score ± SEM'); %[output:9305bb70]
ColorBar.Label.String='z-score'; %[output:9305bb70]
MATLAB.Graphics.FigureAspectRatio(8,5,MATLAB.Flags.Narrow); %[output:9305bb70]
title(Layout,'Ensemble Learned') %[output:9305bb70]
print(Fig,TransferLearning.ProjectPath('Fig2C.svg'),'-dsvg'); %[output:9305bb70]
%%
%[text] ## D
%[text] 时间统计
Fig=figure; %[output:7417889d]
Layout=tiledlayout(1,2,TileSpacing='tight',Padding='compact'); %[output:7417889d]
%%
EnsembleCDE.Naive.Phase(:)="Naive";
EnsembleCDE.Learned.Phase(:)="Learned";
EnsembleD=[EnsembleCDE.Naive;EnsembleCDE.Learned];
EnsembleD=EnsembleD(max(EnsembleD.NTATS(:,25:32),[],2)>std(EnsembleD.NTATS(:,1:24),[],2)*3,:);
[~,Index]=ismember(EnsembleD.CellUID,ALB.Cells.CellUID);
EnsembleD.ZLayer=ALB.Cells.ZLayer(Index);
%%
[~,RisingTime]=max(diff(EnsembleD.NTATS(:,25:end),1,2),[],2);
EnsembleD.RisingTime=RisingTime*milliseconds(125);
%%
TimeComparison=UniExp.TabularAnovaN(EnsembleD.RisingTime,EnsembleD(:,["Phase","ZLayer"]),Comparison=table(["Naive","Learned";"Naive","Learned";"Learned","Learned"],["MOp2/3","MOp2/3";"MOp5","MOp5";"MOp2/3","MOp5"],'VariableNames',["Phase","ZLayer"]),Model=2,Display=false);
%%
BarData=groupsummary(EnsembleD,["Phase","ZLayer"],["mean","std"],"RisingTime");
BarData.SEM=BarData.std_RisingTime./sqrt(BarData.GroupCount);
%%
nexttile; %[output:85ed4c24]
Bars=bar(reshape(BarData.mean_RisingTime,2,2)); %[output:85ed4c24]
hold on; %[output:85ed4c24]
errorbar([Bars.XEndPoints],[Bars.YEndPoints],[],BarData.SEM,'k',LineWidth=2,LineStyle='none'); %[output:85ed4c24]
PX=vertcat(Bars.XEndPoints);
YLim=ylim;
LevelStep=YLim(2)/10;
PY=max(reshape(BarData.mean_RisingTime+BarData.SEM,2,2),[],2).'+LevelStep;
PY=[PY;PY];
line(PX,PY,Color='k'); %[output:85ed4c24]
PY=PY(1,:)+LevelStep;
text(1:2,PY,"p="+MATLAB.SignificantFixedpoint(TimeComparison.PValue(1:2),2),HorizontalAlignment='center',VerticalAlignment='top',AffectAutoLimits=true); %[output:85ed4c24]
PY=max(PY);
line(PX(1,:),[PY,PY],Color='k'); %[output:85ed4c24]
text(mean(PX(1,:)),PY+LevelStep,"p="+MATLAB.SignificantFixedpoint(TimeComparison.PValue(3),2),HorizontalAlignment='center',VerticalAlignment='top',AffectAutoLimits=true); %[output:85ed4c24]
colororder([1,0,1;0,0.5,0]); %[output:85ed4c24]
YLim=ylim;
ylim([0,YLim(2)]); %[output:85ed4c24]
xticklabels(["Layer 2","Layer 5"]); %[output:85ed4c24]
ylabel('Rising time'); %[output:85ed4c24]
%%
%[text] 峰值统计
EnsembleD.Response=max(EnsembleD.NTATS(:,25:32),[],2);
ResponseComparison=UniExp.TabularAnovaN(EnsembleD.Response,EnsembleD(:,["Phase","ZLayer"]),Comparison=table(["Naive","Learned";"Naive","Learned"],["MOp2/3","MOp2/3";"MOp5","MOp5"],'VariableNames',["Phase","ZLayer"]),Model=2,Display=false);
BarData=groupsummary(EnsembleD,["Phase","ZLayer"],["mean","std"],"Response");
BarData.SEM=BarData.std_Response./sqrt(BarData.GroupCount);
nexttile; %[output:8cc31c66]
Bars=bar(reshape(BarData.mean_Response,2,2)); %[output:8cc31c66]
hold on; %[output:8cc31c66]
errorbar([Bars.XEndPoints],[Bars.YEndPoints],[],BarData.SEM,'k',LineWidth=2,LineStyle='none'); %[output:8cc31c66]
PX=vertcat(Bars.XEndPoints);
YLim=ylim;
LevelStep=YLim(2)/10;
PY=max(reshape(BarData.mean_Response+BarData.SEM,2,2),[],2).'+LevelStep;
PY=[PY;PY];
line(PX,PY,Color='k'); %[output:8cc31c66]
text(1:2,PY(1,:)+LevelStep,"p="+MATLAB.SignificantFixedpoint(ResponseComparison.PValue(1:2),2),HorizontalAlignment='center',VerticalAlignment='top',AffectAutoLimits=true); %[output:8cc31c66]
colororder([1,0,1;0,0.5,0]); %[output:8cc31c66]
legend(Bars,unique(BarData.Phase),Location='northeast'); %[output:8cc31c66]
YLim=ylim;
ylim([0,YLim(2)]); %[output:8cc31c66]
xticklabels(["Layer 2","Layer 5"]); %[output:8cc31c66]
ylabel('Max z-score in 1s'); %[output:8cc31c66]
%%
MATLAB.Graphics.FigureAspectRatio(8,5,MATLAB.Flags.Narrow); %[output:8d5711cd]
print(Fig,TransferLearning.ProjectPath('Fig2D.svg'),'-dsvg'); %[output:8d5711cd]
%%
%[text] ## E
%[text] 相关性亚群
EnsembleE=EnsembleCDE.Learned;
EnsembleE=EnsembleE(max(EnsembleE.NTATS(:,25:32),[],2)>std(EnsembleE.NTATS(:,1:24),[],2)*3,:);
Correlation=corrcoef(normalize(EnsembleE.NTATS,2,'zscore').');


